// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AgentTurn) predicate.AgentTurn {
	return predicate.AgentTurn(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AgentTurn) predicate.AgentTurn {
	return predicate.AgentTurn(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AgentTurn) predicate.AgentTurn {
	return predicate.AgentTurn(sql.NotPredicates(p))
}
